import { isSameDay } from 'date-fns';
import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { formatDate } from '@dynatrace-sdk/units';

import { useCalendarContext } from './useCalendarContext.js';
import { useFocus } from './useFocus.js';
import { _isTimeframeV2 } from '../../../forms-core/time/types.js';
import type { ViewItem } from '../CalendarItem.js';
import type { UseCalendarItemProps } from '../types/shared-types.js';
import { _getHighlightingProps, _isOutOfBounds } from '../utils/helpers.js';

/** Custom hook that retrieves properties from the current day. */
export function useDay({ date, itemRef }: UseCalendarItemProps): ViewItem {
  const { state, dispatch } = useCalendarContext();

  const intl = useIntl();

  const ariaLabel = useMemo(() => {
    const formatMessage = intl.formatMessage({
      defaultMessage: 'Select day',
      id: 'UBJSASimMVkN5w7p',
      description: 'Aria label to add to each day button',
    });

    return `${formatMessage} ${formatDate(date, {
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      // Extract the user-settings timezone to use for the calculation
      timeZone:
        intl.timeZone ?? Intl.DateTimeFormat().resolvedOptions().timeZone,
    })}`;
  }, [date, intl]);

  const isCurrent = useMemo(
    () => isSameDay(date, state.today),
    [date, state.today],
  );

  const isFocused = useMemo(
    () => isSameDay(date, state.activeDate),
    [date, state.activeDate],
  );

  const {
    highlightType,
    highlightColor,
    isSelected,
    selectionVariant,
  }: Pick<
    ViewItem,
    'isSelected' | 'highlightColor' | 'highlightType' | 'selectionVariant'
  > = useMemo(() => _getHighlightingProps(date, state), [date, state]);

  const isDisabled = useMemo(
    () => _isOutOfBounds(date.toISOString(), state.min, state.max),
    [date, state.min, state.max],
  );

  const { tabIndex } = useFocus({ isFocused, itemRef });

  /** Handle click on a day in the select day view. */
  function onClick(
    event?:
      | React.MouseEvent<HTMLDivElement>
      | React.KeyboardEvent<HTMLDivElement>,
  ) {
    dispatch({
      type: 'selectionChanged',
      payload: date,
    });

    dispatch({ type: 'isCalendarBodyFocusedChange', payload: false });
  }

  const rangeInteractionProps =
    // only need to listen to hover if only one date is selected in a range.
    _isTimeframeV2(state.selectedDate, state.type) &&
    state.selectedDate.from &&
    !state.selectedDate.to
      ? {
          onMouseEnter: () => {
            dispatch({ type: 'hoveredItemChanged', payload: date });
          },
        }
      : {};

  return {
    ariaLabel,
    tabIndex,
    isCurrent,
    onClick,
    isDisabled,
    rangeInteractionProps,
    isSelected,
    highlightColor,
    highlightType,
    selectionVariant,
  };
}
